def _build(lesson_id):
    vocab = []
    for raw in VOCAB[lesson_id]:
        french, meaning, pronunciation, ipa = raw.split("|", 3)
        vocab.append((french, meaning, pronunciation, ipa, f"Il faut comprendre « {french} » dans son contexte. — Understand « {french} » in context."))
    grammar = GRAMMAR[lesson_id]
    exercises = []
    for i, item in enumerate(vocab[:5]):
        options = [item[1]]
        for step in range(1, len(vocab)):
            candidate = vocab[(i + step) % len(vocab)][1]
            if candidate not in options:
                options.append(candidate)
            if len(options) == 4:
                break
        exercises.append((f"What does « {item[0]} » mean?", options, 0, f"« {item[0]} » means {item[1]}."))
    for i, item in enumerate(grammar[:5]):
        exercises.append((f"Which statement best describes: {item[0]}?", [item[1], grammar[(i+1)%6][1], grammar[(i+2)%6][1], grammar[(i+3)%6][1]], 0, item[1]))
    examples = [
        ("Bien que la situation soit complexe, nous devons agir avec prudence.","Although the situation is complex, we must act carefully.","The subjunctive after bien que marks concession."),
        ("Rétrospectivement, je me rends compte que cette décision avait tout changé.","In retrospect, I realise that this decision had changed everything.","Plus-que-parfait places the change before a later past reference point."),
        ("Si nous avions disposé de davantage de temps, nous aurions approfondi la question.","If we had had more time, we would have explored the issue further.","This is an unreal past condition and result."),
        ("Cette interprétation est pertinente, quoique quelque peu réductrice.","This interpretation is relevant, although somewhat reductive.","Quoique introduces a concession; quelque peu qualifies the adjective."),
        ("Il serait souhaitable que chacun puisse exprimer son point de vue.","It would be desirable for everyone to be able to express their point of view.","The subjunctive puisse follows an evaluative impersonal expression."),
        ("Je vous propose que nous reprenions les principaux enjeux avant de conclure.","I suggest that we review the main issues before concluding.","A formal proposal uses the subjunctive after proposer que.")
    ]
    conversations = [
        ("A nuanced professional discussion",[("A","Je comprends votre réserve, mais il me semble que les données méritent une autre interprétation."),("B","C'est possible. Encore faudrait-il vérifier si l'échantillon est représentatif."),("A","Tout à fait. Je propose que nous examinions cette question avant de prendre une décision.")],"A: I understand your concern, but it seems to me that the data deserve another interpretation. B: Possibly. We would still need to check whether the sample is representative. A: Absolutely. I suggest that we examine this issue before making a decision."),
        ("An informal conversation in Quebec",[("A","T'es encore dans le jus au travail ?"),("B","Oui, pas mal. J'ai plusieurs dossiers à terminer avant la fin de semaine."),("A","Ouin, prends ça relax quand tu peux !")],"A: Are you still swamped at work? B: Yes, quite a bit. I have several files to finish before the weekend. A: Yeah, take it easy when you can! This dialogue uses informal Quebec-style speech; standard forms are appropriate in formal writing."),
        ("Clarifying a literary interpretation",[("A","Comment interprétez-vous la fin du roman ?"),("B","Je la trouve volontairement ambiguë. Le narrateur ne révèle jamais toute la vérité."),("A","Donc, le lecteur doit tenir compte du sous-texte ?"),("B","Exactement, et aussi du point de vue adopté tout au long du récit.")],"A: How do you interpret the ending of the novel? B: I find it deliberately ambiguous. The narrator never reveals the whole truth. A: So the reader must take the subtext into account? B: Exactly, as well as the point of view used throughout the story.")
    ]
    speaking = [
        "Give a two-minute explanation of the lesson topic, using target expressions and a clear introduction and conclusion.",
        "Explain one complex idea in formal, neutral conversational and informal language. Notice how register changes vocabulary and syntax.",
        "Practise the dialogues aloud, then repeat them without reading and adapt the details to a new situation.",
        "Build five original sentences using the grammar points. Explain why you selected each tense, mood or connector.",
        "Listen to an authentic Canadian French interview or news segment. Summarise the main idea, then note discourse markers and reductions.",
        "Respond spontaneously to an opposing opinion. Acknowledge one valid point, state your position and support it with an example.",
        "Paraphrase a difficult sentence without changing its central meaning. Avoid translating word for word.",
        "Review your speech for clarity, accuracy, cohesion and register. Repeat the weakest passage with a more precise structure."
    ]
    summary = [f"Understand and use the central concepts in « {TITLES[lesson_id]} ».","Apply the grammar patterns deliberately, paying attention to meaning, chronology and register.","Choose precise vocabulary and connectors to make complex ideas coherent.","Recognise Canadian French variation while adapting your language to the audience and situation.","Use listening, reading, speaking and writing practice to build flexible advanced communication."]
    assessment = APPLICATION[:]
    topic_examples = [(f"Dans le cadre de « {TITLES[lesson_id]} », le terme « {vocab[0][0]} » doit être interprété avec précision.", f"In the context of {TITLES[lesson_id]}, the term « {vocab[0][0]} » must be interpreted precisely.", "This lesson-specific example applies the chapter vocabulary in a precise sentence.")]
    examples = topic_examples + examples
    topic_conversation = (f"Clarifying {TITLES[lesson_id].lower()}", [("A", f"Comment interprétez-vous « {vocab[0][0]} » ?"), ("B", "Il faut tenir compte du contexte, du sens et du registre."), ("A", "La situation change-t-elle l'interprétation ?"), ("B", "Oui, le contexte permet de préciser le sens.")], f"A: How do you interpret « {vocab[0][0]} »? B: We must take context, meaning and register into account. A: Does the situation change the interpretation? B: Yes, context helps clarify the meaning.")
    conversations = [topic_conversation] + conversations
    return {"title":TITLES[lesson_id],"goal":GOALS[lesson_id],"vocab":vocab,"vocabulary":vocab,"grammar":grammar,"expressions":EXPRESSIONS,"examples":examples,"conversations":conversations,"exercises":exercises,"speaking":speaking,"summary":summary,"assessment":assessment}
C1_LESSONS = {lesson_id:_build(lesson_id) for lesson_id in range(61,76)}
